def remove_replica(test_tup):
    """Write a function to remove tuple elements that occur more than once and replace the duplicates with some custom value."""
    seen_hashable = set()
    seen_unhashable = []
    result = []
    for item in test_tup:
        try:
            if item in seen_hashable:
                result.append('MSP')
                continue
            seen_hashable.add(item)
        except TypeError:
            if any(item == seen_item for seen_item in seen_unhashable):
                result.append('MSP')
                continue
            seen_unhashable.append(item)
        result.append(item)
    return tuple(result)
